package status

// WantsBlink reports whether the footer needs the router's blink frames. It
// follows what is displayed: an auto-refresh shows no dot, so it asks for none.
// status() is a pure function of the model, so calling it has no side effect.
func (m Model) WantsBlink() bool { return m.status().Activity }
package status

import (
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-369 T1: the check is reported by the shared activity dot, driven by
// the router's blink phase, not by a spinner of this view's own.

var checkingActivity = struct {
	Text     string
	Activity bool
}{"Checking components...", true}

// wantsBlink asks the view whether it wants the router's blink chain. Through an
// interface assertion, so the suite compiles (and fails on the assertion) until
// the view implements it.
func wantsBlink(m Model) bool {
	b, ok := any(m).(interface{ WantsBlink() bool })
	return ok && b.WantsBlink()
}

func wantChecking(t *testing.T, m Model, what string) {
	t.Helper()
	st := m.status()
	if st.Text != checkingActivity.Text || !st.Activity {
		t.Errorf("%s: status() = %+v, want Text %q and Activity", what, st, checkingActivity.Text)
	}
}

func TestStatusViewImplementsWantsBlink(t *testing.T) {
	if _, ok := any(Model{}).(interface{ WantsBlink() bool }); !ok {
		t.Error("status.Model has no WantsBlink() bool, so the router never arms the blink chain for it")
	}
}

func TestStatusActivityFirstCheckShowsTheDot(t *testing.T) {
	m := newTestModel(t, monitorConfigs()...)
	wantChecking(t, m, "a new model, before the first check answers")
	if !wantsBlink(m) {
		t.Error("WantsBlink() = false while the first check runs")
	}
}

func TestStatusActivityManualRefreshShowsTheDot(t *testing.T) {
	m := loadedModel(t)
	if m.status().Activity || wantsBlink(m) {
		t.Fatalf("fixture error: a loaded model reports activity: %+v", m.status())
	}
	m, _ = step(t, m, testutil.Key("ctrl+r"))
	wantChecking(t, m, "ctrl+r")
	if !wantsBlink(m) {
		t.Error("WantsBlink() = false after ctrl+r")
	}
}

func TestStatusActivityConfigReloadShowsTheDot(t *testing.T) {
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("USERPROFILE", home)
	m := loadedModel(t)
	m, _ = step(t, m, ComponentSavedMsg{Success: true})
	wantChecking(t, m, "a config reload")
}

func TestStatusActivityAutoRefreshShowsNoDot(t *testing.T) {
	m := loadedModel(t)
	m.autoRefresh = true
	m.nextCheck = time.Now().Add(-time.Minute)
	m, _ = step(t, m, TickMsg{})
	if !m.checking {
		t.Fatal("fixture error: the due tick started no check")
	}
	if st := m.status(); st.Activity || wantsBlink(m) {
		t.Errorf("an auto-refresh shows the dot: status() = %+v", st)
	}
}

func TestStatusActivityEndsWithTheCheck(t *testing.T) {
	m := newTestModel(t, monitorConfigs()...)
	m, _ = step(t, m, CheckCompleteMsg{Components: checkResults(), Timestamp: time.Now()})
	if st := m.status(); st.Text != "" || st.Activity {
		t.Errorf("status() = %+v after CheckCompleteMsg, want empty", st)
	}
	if wantsBlink(m) {
		t.Error("WantsBlink() = true after the check ended")
	}
}

func TestStatusFooterFollowsTheBlinkPhase(t *testing.T) {
	m := newTestModel(t, monitorConfigs()...)
	on, off := indicator.Glyph(indicator.Running, true), indicator.Glyph(indicator.Running, false)

	m, _ = step(t, m, jobs.FrameMsg{Blink: false})
	f := ansi.Strip(m.RenderFooter(120))
	if strings.Count(f, off) != 1 || strings.Contains(f, on) {
		t.Errorf("Blink:false footer = %q, want exactly one %s", f, off)
	}
	m, _ = step(t, m, jobs.FrameMsg{Blink: true})
	f = ansi.Strip(m.RenderFooter(120))
	if strings.Count(f, on) != 1 || strings.Contains(f, off) {
		t.Errorf("Blink:true footer = %q, want exactly one %s", f, on)
	}
}

// No spinner of the view's own: the package imports neither bubbles/spinner nor
// uses a spinner.Model.
func TestStatusViewHasNoSpinner(t *testing.T) {
	files, err := filepath.Glob("*.go")
	if err != nil {
		t.Fatal(err)
	}
	for _, name := range files {
		if strings.HasSuffix(name, "_test.go") {
			continue
		}
		src, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		file, err := parser.ParseFile(token.NewFileSet(), name, src, parser.ImportsOnly)
		if err != nil {
			t.Fatal(err)
		}
		for _, imp := range file.Imports {
			if p, _ := strconv.Unquote(imp.Path.Value); strings.HasSuffix(p, "/spinner") {
				t.Errorf("%s imports %s: report the check with the activity dot", name, p)
			}
		}
		if strings.Contains(string(src), "spinner.Model") {
			t.Errorf("%s uses spinner.Model", name)
		}
	}
}

tools.description:
Work items -- issues, tasks and epics.

Actions:
  list (no required params; optional project_id, pql, order_by, per_page, cursor, expand, fields, external_id, external_source) -- omit project_id to search the whole workspace;
  list_archived (project_id; optional pql, order_by, per_page, cursor, expand, fields, external_id, external_source);
  retrieve (project_id, workitem_id; optional expand, fields, external_id, external_source, order_by);
  retrieve_by_identifier (workitem_identifier; optional expand, fields, external_id, external_source, order_by) -- identifier is PROJECT-N, e.g. ENG-42;
  search (query; optional expand, fields, external_id, external_source, order_by);
  count (no required params; optional project_id, pql, group_by, sub_group_by) -- counts the whole workspace unless project_id narrows it;
  create (project_id, name; optional assignees, labels, type_id, point, description_html, description_stripped, priority, start_date, target_date, sort_order, is_draft, parent, state, estimate_point, external_source, external_id);
  update (project_id, workitem_id; optional name, assignees, labels, type_id, point, description_html, description_stripped, priority, start_date, target_date, sort_order, is_draft, parent, state, estimate_point, external_source, external_id) -- only the fields you pass are changed;
  delete (project_id, workitem_id);
  archive (project_id, workitem_id; optional archive) -- archive defaults to true; pass archive=false to unarchive. Only completed or cancelled items can be archived;
  manage_assignee (project_id, workitem_id; optional add_user_id, remove_user_id) -- each takes one id or several; the list is merged, not replaced, and removals apply first;
  manage_label (project_id, workitem_id; optional add_label_id, remove_label_id) -- each takes one id or several; the list is merged, not replaced, and removals apply first.

priority: urgent, high, medium, low, none.
UUID fields (assignees, labels, state, parent, type_id) need UUIDs -- list the relevant resource first if you only have a name.
description_stripped is plain text and is wrapped into HTML on save; description_html wins if both are given.
To clear a field on update: assignees=[] or labels=[], and start_date=null or target_date=null. A field you leave out is not changed.
fields is a sparse fieldset: use `project`, not project_id, and `description_html`, not description.
count group_by and sub_group_by accept: state_id, state__group, priority, project_id, type_id, labels__id, assignees__id, issue_module__module_id, release_work_items__release_id, cycle_id, milestone_id, created_by, target_date, start_date. These are grouping keys only -- they are not PQL filter fields, and filtering on state__group is rejected.

Comments on a work item.

Actions:
  list (project_id, workitem_id; optional cursor, per_page);
  retrieve (project_id, workitem_id, comment_id);
  create (project_id, workitem_id, comment_html; optional access, external_source, external_id);
  update (project_id, workitem_id, comment_id; optional comment_html, access, external_source, external_id);
  delete (project_id, workitem_id, comment_id).

comment_html is HTML, e.g. '<p>Looks good.</p>'. access is INTERNAL or EXTERNAL.
To mention someone, write @[<user uuid>] inline -- '<p>@[<user uuid>] can you review?</p>' -- and the chip and the notification are generated for you. A bare @name is ordinary text that notifies nobody. The id must belong to a member of the work item's project; `member list_project` resolves a name to one. Mentions read back in the same form.

